Para vender tokens de forma privada a inversores tempranos antes de su lanzamiento público, sí es necesario crear un contrato de preventa separado del contrato principal.

Aquí te presentamos un esquema de los pasos que puedes seguir para crear un contrato de preventa separado en Solidity:

1. Definir variables: Declara variables necesarias como `address payable` para el propietario del contrato, `uint256` para el número de tokens disponibles, `uint256` para el precio por token, y un array de direcciones de los inversores que han adquirido tokens durante el período de preventa.

2. Constructor: Define un constructor que establezca el propietario del contrato, el número de tokens disponibles, el precio por token, y un mensaje de inicio.

3. Métodos de preventa: Define métodos para iniciar la preventa, comprar tokens, cancelar preventas, y finalizar la preventa.

4. Métodos de administración: Define métodos para permitir que el propietario del contrato administre la preventa, como actualizar el número de tokens disponibles, el precio por token, y el mensaje de inicio.

5. Eventos: Define eventos para cada acción realizada durante la preventa, como el inicio, la compra, la cancelación, y el final.

6. Transferencia de tokens: Define una función de transferencia de tokens que transfiera los tokens comprados durante la preventa a las direcciones de los inversores.

7. Comprobar el estado de preventa: Define una función de estado de preventa que devuelva true si el período de preventa ha finalizado, de lo contrario false.

8. Garantía de exclusividad: Para garantizar que los inversores que participen en la preventa tengan prioridad sobre los inversores que participen en el lanzamiento público, puedes agregar un mecanismo de exclusividad, como requerir que los inversores que participen en la preventa mantengan sus tokens durante un período de tiempo específico después del final de la preventa.

Aquí te presentamos un ejemplo de un contrato de preventa separado en Solidity:

```solidity
pragma solidity ^0.8.0;

contract Preventa {

    address payable public owner;
    uint256 public numTokensAvailable;
    uint256 public pricePerToken;
    string public message;

    mapping(address => uint256) public preventaBalances;
    address[] public preventaParticipants;

    event PreventaStarted(address indexed sender);
    event TokenPurchased(address indexed purchaser, uint256 indexed tokenId);
    event PreventaCancelled();
    event PreventaFinalized();

    constructor(uint256 _numTokensAvailable, uint256 _pricePerToken, string memory _message) payable {
        owner = payable(msg.sender);
        numTokensAvailable = _numTokensAvailable;
        pricePerToken = _pricePerToken;
        message = _message;

        emit PreventaStarted(msg.sender);
    }

    function startPreventa() external onlyOwner {
        require(!isPreventaFinalized(), "Preventa ya finalizada");

        emit PreventaStarted(msg.sender);
    }

    function buyToken() external payable {
        require(isPreventaOpen(), "Preventa cerrada");
        require(msg.value >= pricePerToken, "No suficiente ETH enviada");

        uint256 tokenId = preventaBalances[msg.sender] + 1;

        preventaBalances[msg.sender] += 1;
        preventaParticipants.push(msg.sender);

        emit TokenPurchased(msg.sender, tokenId);
    }

    function cancelPreventa() external onlyOwner {
        require(!isPreventaFinalized(), "Preventa ya finalizada");

        emit PreventaCancelled();
    }

    function finalizePreventa() external onlyOwner {
        require(!isPreventaFinalized(), "Preventa ya finalizada");

        uint256 totalTokensSold = preventaParticipants.length;

        if (totalTokensSold > numTokensAvailable) {
            revert("Número de tokens vendidos excede el número disponible");
        }

        for (uint256 I = 0; I < preventaParticipants.length; i++) {
            address participant = preventaParticipants[i];
            uint256 numTokensBought = preventaBalances[participant];

            if (numTokensBought > 0) {
                transferTokens(participant, numTokensBought);
            }
        }

        emit PreventaFinalized();
    }

    function updateNumTokensAvailable(uint256 _numTokensAvailable) external onlyOwner {
        numTokensAvailable = _numTokensAvailable;
    }

    function updatePricePerToken(uint256 _pricePerToken) external onlyOwner {
        pricePerToken = _pricePerToken;
    }

    function updateMessage(string memory _message) external onlyOwner {
        message = _message;
    }

    function isPreventaOpen() view public returns (bool) {
        return !isPreventaFinalized();
    }

    function isPreventaFinalized() view public returns (bool) {
        return preventaParticipants.length >= numTokensAvailable;
    }

    function transferTokens(address _to, uint256 _numTokens) private {
        for (uint256 I = 0; I < _numTokens; i++) {
            emit TokenPurchased(_to, preventaBalances[_to] + I + 1);
        }
    }
}
```

