public class PotenciaDeTres {

    public static boolean esPotenciaDeTres(int n) {
        if (n < 0 || n == 0) { // Excluir valores negativos o cero
            return false;
        }

        int log3n = (int) Math.log(n) / Math.log(3); // Calcular logaritmo base 3 de n
        return Math.pow(3, log3n) == n; // Comprobar si 3 elevado a la potencia log3n es igual a n
    }

